<?php
require_once __DIR__ . '/../inc/auth.php'; require_once __DIR__ . '/../config/database.php';
$page_title = 'Transaction History'; $active_page = 'history'; $search = trim($_GET['search'] ?? ''); $status = $_GET['status'] ?? ''; $type = $_GET['assistance_type'] ?? ''; $date = $_GET['date'] ?? '';
$sql = 'SELECT h.*, r.request_id AS request_code, r.full_name, r.assistance_type, r.amount_requested, r.date_of_visit, r.status FROM transaction_history h JOIN requests r ON r.id = h.request_id WHERE 1=1'; $params = array(); if ($search !== '') { $sql .= ' AND (r.request_id LIKE ? OR r.full_name LIKE ?)'; $term = '%' . $search . '%'; $params = array($term, $term); } if (in_array($status, array('Pending','Approved','Completed','Rejected'), true)) { $sql .= ' AND r.status = ?'; $params[] = $status; } if (in_array($type, array('Financial Assistance','Medical Assistance','Educational Assistance','Solicitation','Other'), true)) { $sql .= ' AND r.assistance_type = ?'; $params[] = $type; } if ($date !== '') { $sql .= ' AND r.date_of_visit = ?'; $params[] = $date; } $sql .= ' ORDER BY h.created_at DESC'; $statement = $pdo->prepare($sql); $statement->execute($params); $history = $statement->fetchAll(); include __DIR__ . '/../inc/header.php';
?>
<div class="welcome-row"><div><p class="muted">A complete trail of status changes</p><h2 class="section-title">Transaction history</h2></div></div><section class="panel"><form class="filter-bar" method="get"><div class="search-box"><i class="bi bi-search"></i><input name="search" value="<?= e($search); ?>" placeholder="Search request ID or name"></div><select name="status"><option value="">All statuses</option><?php foreach (array('Pending','Approved','Completed','Rejected') as $option): ?><option value="<?= e($option); ?>" <?= $status === $option ? 'selected' : ''; ?>><?= e($option); ?></option><?php endforeach; ?></select><select name="assistance_type"><option value="">All assistance types</option><?php foreach (array('Financial Assistance','Medical Assistance','Educational Assistance','Solicitation','Other') as $option): ?><option value="<?= e($option); ?>" <?= $type === $option ? 'selected' : ''; ?>><?= e($option); ?></option><?php endforeach; ?></select><input type="date" name="date" value="<?= e($date); ?>"><button class="btn btn-dark" type="submit">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Request ID</th><th>Requester</th><th>Type</th><th>Amount</th><th>Date</th><th>Status</th><th>Processed By</th><th></th></tr></thead><tbody><?php foreach ($history as $item): ?><tr><td><strong class="request-code"><?= e($item['request_code']); ?></strong></td><td><?= e($item['full_name']); ?></td><td><?= e($item['assistance_type']); ?></td><td>PHP <?= e(format_amount($item['amount_requested'])); ?></td><td><?= e(date('M d, Y', strtotime($item['created_at']))); ?></td><td><span class="status <?= e(status_class($item['new_status'])); ?>"><?= e($item['previous_status']); ?> <i class="bi bi-arrow-right"></i> <?= e($item['new_status']); ?></span></td><td><?= e($item['processed_by']); ?></td><td><a class="icon-link" href="view_request.php?id=<?= e($item['request_id']); ?>"><i class="bi bi-arrow-up-right"></i></a></td></tr><?php endforeach; ?><?php if (!$history): ?><tr><td colspan="8" class="empty-state">No status changes found.</td></tr><?php endif; ?></tbody></table></div></section>
<?php include __DIR__ . '/../inc/footer.php'; ?>
